{
  "name": "QuTech量子控制箱",
  "name_en": "QuTech Control Box",
  "manufacturer": "QuTech",
  "description": "用于量子比特实验的200 MS/s控制与读出电子学设备。该控制箱通过串行协议进行通信，可配置AWG查找表、DAC使能与偏置、分段/条件时序带，并读取输入平均、积分平均、积分日志、量子态日志及流式采集结果，常用于量子测控与读出实验。",
  "description_en": "A 200 MS/s control and readout electronics unit for qubit experiments. The control box communicates over a serial protocol and supports configuring AWG lookup tables, DAC enable and offsets, segmented/conditional timing tapes, and reading input-average, integrated-average, integration-log, qubit-state-log, and streaming acquisition results for quantum control and readout experiments.",
  "actions": [
    {
      "action_name": "auto-add_params",
      "description": "添加控制箱驱动参数定义。",
      "description_en": "Add the control box driver parameter definitions."
    },
    {
      "action_name": "auto-init_params",
      "description": "初始化控制箱参数。",
      "description_en": "Initialize the control box parameters."
    },
    {
      "action_name": "auto-run_test_suite",
      "description": "运行面向控制箱的测试套件。",
      "description_en": "Run the test suite for the control box."
    },
    {
      "action_name": "auto-get_all",
      "description": "读取控制箱的全部已公开参数和状态。",
      "description_en": "Read all exposed parameters and states from the control box."
    },
    {
      "action_name": "auto-upload_standard_weights",
      "description": "向控制箱上传指定中频的标准权重。",
      "description_en": "Upload standard weights for the specified intermediate frequency to the control box."
    },
    {
      "action_name": "auto-decode_message",
      "description": "解码控制箱返回的协议消息。",
      "description_en": "Decode a protocol message returned by the control box."
    },
    {
      "action_name": "auto-create_message",
      "description": "创建发送给控制箱的协议消息。",
      "description_en": "Create a protocol message to send to the control box."
    },
    {
      "action_name": "auto-get_input_avg_results",
      "description": "读取ADC输入平均结果。",
      "description_en": "Read the ADC input-average results."
    },
    {
      "action_name": "auto-get_integrated_avg_results",
      "description": "读取积分平均测量结果。",
      "description_en": "Read the integrated-average measurement results."
    },
    {
      "action_name": "auto-get_integration_log_results",
      "description": "读取积分日志数据。",
      "description_en": "Read the integration log data."
    },
    {
      "action_name": "auto-get_qubit_state_log_results",
      "description": "读取量子态日志结果。",
      "description_en": "Read the qubit state log results."
    },
    {
      "action_name": "auto-get_qubit_state_log_counters",
      "description": "读取量子态日志计数器值。",
      "description_en": "Read the qubit state log counter values."
    },
    {
      "action_name": "auto-send_stop_streaming",
      "description": "发送停止流式采集命令。",
      "description_en": "Send the command to stop streaming acquisition."
    },
    {
      "action_name": "auto-get_streaming_results",
      "description": "获取流式采集数据。",
      "description_en": "Get the streaming acquisition data."
    },
    {
      "action_name": "auto-set_awg_lookuptable",
      "description": "设置指定AWG、表号和DAC通道的查找表波形值。",
      "description_en": "Set the lookup-table waveform values for the specified AWG, table number, and DAC channel."
    },
    {
      "action_name": "auto-restart_awg_tape",
      "description": "重启或复位指定AWG的时序带指针。",
      "description_en": "Restart or reset the timing tape pointer for the specified AWG."
    },
    {
      "action_name": "auto-enable_dac",
      "description": "使能或静音指定DAC通道。",
      "description_en": "Enable or mute the specified DAC channel."
    },
    {
      "action_name": "auto-set_dac_offset",
      "description": "设置指定DAC通道的输出偏置。",
      "description_en": "Set the output offset of the specified DAC channel."
    },
    {
      "action_name": "auto-get_dac_offset",
      "description": "读取指定DAC通道的输出偏置。",
      "description_en": "Get the output offset of the specified DAC channel."
    },
    {
      "action_name": "auto-set_ecc_truthtable",
      "description": "定义ECC真值表（方法注明未实现）。",
      "description_en": "Define the ECC truth table (marked as not implemented)."
    },
    {
      "action_name": "auto-set_averaging_parameters",
      "description": "设置平均测量的采样点数和平均长度。",
      "description_en": "Set the sample count and averaging size for averaging measurements."
    },
    {
      "action_name": "auto-serial_read",
      "description": "从串行接口读取控制箱协议数据。",
      "description_en": "Read control box protocol data from the serial interface."
    },
    {
      "action_name": "auto-serial_write",
      "description": "通过串行接口写入控制箱协议数据并可校验执行结果。",
      "description_en": "Write control box protocol data through the serial interface and optionally verify execution."
    },
    {
      "action_name": "auto-set_conditional_tape",
      "description": "设置指定AWG的条件时序带内容。",
      "description_en": "Set the conditional timing tape content for the specified AWG."
    },
    {
      "action_name": "auto-set_segmented_tape",
      "description": "设置指定AWG的分段时序带内容。",
      "description_en": "Set the segmented timing tape content for the specified AWG."
    },
    {
      "action_name": "auto-create_timing_tape_entry",
      "description": "根据等待时间、脉冲编号和标记位创建时序带条目。",
      "description_en": "Create a timing tape entry from wait time, pulse number, and marker settings."
    },
    {
      "action_name": "auto-convert_to_signed",
      "description": "按给定位宽将无符号整数转换为有符号整数。",
      "description_en": "Convert an unsigned integer to a signed integer using the specified bit width."
    },
    {
      "action_name": "auto-convert_arrary_to_signed",
      "description": "按给定位宽将无符号整数数组转换为有符号数组。",
      "description_en": "Convert an unsigned integer array to a signed array using the specified bit width."
    }
  ],
  "tag_hints": [
    "quantum control electronics",
    "qubit readout",
    "200 MS/s",
    "AWG waveform generation",
    "DAC offset control",
    "integration logging",
    "qubit state logging",
    "serial instrument communication"
  ]
}

